          </div>
          <div class="result-header">
            <span class="result-title">${f.templateName}</span>
            <span class="result-status status-${f.status || 'draft'}">${f.status === 'completed' ? '✅ Завершено' : '✏️ Черновик'}</span>
          </div>
          <div class="result-meta">
            <span>📅 ${new Date(f.updatedAt).toLocaleString('ru-RU')}</span>
